   242	    /// @notice Requests a withdrawal of shares.
   243	    /// @param shares The amount of shares to withdraw
   244	    function requestWithdrawal(uint128 shares) external {
   245	        uint256 _withdrawalEpoch = withdrawalEpoch;
   246	
   247	        PendingWithdrawal memory pendingWithdrawal = queuedWithdrawal[msg.sender][_withdrawalEpoch];
   248	
   249	        uint256 previousBasis = userBasis[msg.sender];
   250	
   251	        uint256 userBalance = balanceOf[msg.sender];
   252	
   253	        uint256 withdrawalBasis = (previousBasis * shares) / userBalance;
   254	
   255	        userBasis[msg.sender] = previousBasis - withdrawalBasis;
   256	
   257	        queuedWithdrawal[msg.sender][_withdrawalEpoch] = PendingWithdrawal({
   258	            amount: pendingWithdrawal.amount + shares,
   259	            basis: uint128(pendingWithdrawal.basis + withdrawalBasis)
   260	        });
   261	
   262	        withdrawalEpochState[_withdrawalEpoch].sharesWithdrawn += shares;
   263	
   264	        _burnVirtual(msg.sender, shares);
