   272	    /// @param depositor The address that requested the deposit
   273	    function cancelDeposit(address depositor) external onlyManager {
   274	        uint256 currentEpoch = depositEpoch;
   275	
   276	        uint256 queuedDepositAmount = queuedDeposit[depositor][currentEpoch];
   277	        queuedDeposit[depositor][currentEpoch] = 0;
   278	
   279	        depositEpochState[currentEpoch].assetsDeposited -= uint128(queuedDepositAmount);
