   287	    /// @dev Can only be called by the manager.
   288	    /// @dev If withdrawn shares in previous epochs have not been completely fulfilled, the manager can execute those withdrawals to move the unfulfilled amount to the current epoch.
   289	    /// @param withdrawer The address that requested the withdrawal
   290	    function cancelWithdrawal(address withdrawer) external onlyManager {
   291	        uint256 currentEpoch = withdrawalEpoch;
   292	
   293	        PendingWithdrawal memory currentPendingWithdrawal = queuedWithdrawal[withdrawer][
   294	            currentEpoch
   295	        ];
   296	
   297	        queuedWithdrawal[withdrawer][currentEpoch] = PendingWithdrawal({amount: 0, basis: 0});
   298	        userBasis[withdrawer] += currentPendingWithdrawal.basis;
   299	
   300	        withdrawalEpochState[currentEpoch].sharesWithdrawn -= currentPendingWithdrawal.amount;
   301	
   302	        _mintVirtual(withdrawer, currentPendingWithdrawal.amount);
   303	
   304	        emit WithdrawalCancelled(withdrawer, currentPendingWithdrawal.amount);
