   111	
   112	        for (uint256 i = 0; i < pools.length; i++) {
   113	            if (
   114	                Math.abs(
   115	                    managerPrices[i].poolPrice -
   116	                        PanopticMath.twapFilter(pools[i].poolOracle, pools[i].twapWindow)
   117	                ) > pools[i].maxPriceDeviation
   118	            ) revert StaleOraclePrice();
   119	
   120	            uint256[2][] memory positionBalanceArray;
   121	            int256 poolExposure0;
   122	            int256 poolExposure1;
   123	            {
   124	                LeftRightUnsigned shortPremium;
   125	                LeftRightUnsigned longPremium;
   126	
   127	                (shortPremium, longPremium, positionBalanceArray) = pools[i]
   128	                    .pool
   129	                    .getAccumulatedFeesAndPositionsData(_vault, true, tokenIds[i]);
   130	
   131	                poolExposure0 =
   132	                    int256(uint256(shortPremium.rightSlot())) -
   133	                    int256(uint256(longPremium.rightSlot()));
   134	                poolExposure1 =
   135	                    int256(uint256(longPremium.leftSlot())) -
   136	                    int256(uint256(shortPremium.leftSlot()));
   137	            }
   138	
   139	            uint256 numLegs;
   140	            for (uint256 j = 0; j < tokenIds[i].length; j++) {
   141	                if (positionBalanceArray[j][1] == 0) revert IncorrectPositionList();
   142	                uint256 positionLegs = tokenIds[i][j].countLegs();
   143	                for (uint256 k = 0; k < positionLegs; k++) {
   144	                    (uint256 amount0, uint256 amount1) = Math.getAmountsForLiquidity(
   145	                        managerPrices[i].poolPrice,
   146	                        PanopticMath.getLiquidityChunk(
   147	                            tokenIds[i][j],
   148	                            k,
   149	                            uint128(positionBalanceArray[j][1])
   150	                        )
   151	                    );
   152	
   153	                    if (tokenIds[i][j].isLong(k) == 0) {
   154	                        unchecked {
   155	                            poolExposure0 += int256(amount0);
   156	                            poolExposure1 += int256(amount1);
   157	                        }
   158	                    } else {
   159	                        unchecked {
   160	                            poolExposure0 -= int256(amount0);
   161	                            poolExposure1 -= int256(amount1);
   162	                        }
   163	                    }
   164	                }
