   225	                uint160 conversionPrice = Math.getSqrtRatioAtTick(
   226	                    pools[i].isUnderlyingToken0InOracle0 ? -conversionTick : conversionTick
   227	                );
   228	
   229	                poolExposure0 = PanopticMath.convert0to1(poolExposure0, conversionPrice);
   230	            }
   231	
   232	            if (address(pools[i].token1) != underlyingToken) {
   233	                int24 conversionTick = PanopticMath.twapFilter(
   234	                    pools[i].oracle1,
   235	                    pools[i].twapWindow
   236	                );
   237	                if (
   238	                    Math.abs(conversionTick - managerPrices[i].token1Price) >
   239	                    pools[i].maxPriceDeviation
   240	                ) revert StaleOraclePrice();
   241	
   242	                uint160 conversionPrice = Math.getSqrtRatioAtTick(
   243	                    pools[i].isUnderlyingToken0InOracle1 ? conversionTick : -conversionTick
   244	                );
   245	
   246	                poolExposure1 = PanopticMath.convert1to0(poolExposure1, conversionPrice);
   247	            }
