27:    /// @param isUnderlyingToken0InOracle0 Whether token0 in oracle0 is the underlying token
28:    /// @param oracle1 The oracle for token1-underlying
29:    /// @param isUnderlyingToken0InOracle1 Whether token0 in oracle1 is the underlying token
30:    /// @param maxPriceDeviation The maximum price deviation allowed for the oracle prices
31:    /// @param twapWindow The time window (in seconds)to compute the TWAP over
32:    struct PoolInfo {
33:        PanopticPool pool;
34:        IERC20Partial token0;
35:        IERC20Partial token1;
36:        IV3CompatibleOracle poolOracle;
37:        IV3CompatibleOracle oracle0;
38:        bool isUnderlyingToken0InOracle0;
