46:    /// @param poolPrice The price of the pool
47:    /// @param token0Price The price of token0 relative to the underlying
48:    /// @param token1Price The price of token1 relative to the underlying
49:    struct ManagerPrices {
50:        int24 poolPrice;
51:        int24 token0Price;
52:        int24 token1Price;
53:    }
54:
55:    /// @notice An invalid list of pools was provided for the given vault
56:    error InvalidPools();
57:
