65:    error VaultLocked();
66:
67:    /// @notice The hash of pool structs to query for each vault
68:    mapping(address vault => bytes32 poolsHash) public vaultPools;
69:
70:    /// @notice Whether the list of pools for the vault is locked
71:    mapping(address vault => bool isLocked) public vaultLocked;
72:
73:    /// @notice Updates the pools hash for a vault.
74:    /// @dev This function can only be called by the owner of the contract.
75:    /// @param vault The address of the vault to update the pools hash for
76:    /// @param poolsHash The new pools hash to set for the vault
77:    function updatePoolsHash(address vault, bytes32 poolsHash) external onlyOwner {
78:        if (vaultLocked[vault]) revert VaultLocked();
79:        vaultPools[vault] = poolsHash;
80:    }
