88:
89:    /// @notice Returns the NAV of the portfolio contained in `vault` in terms of its underlying token.
90:    /// @param vault The address of the vault to value
91:    /// @param underlyingToken The underlying token of the vault
92:    /// @param managerInput Input calldata from the vault manager consisting of price quotes from the manager, pool information, and a position lsit for each pool
93:    /// @return nav The NAV of the portfolio contained in `vault` in terms of its underlying token
94:    function computeNAV(
95:        address vault,
96:        address underlyingToken,
97:        bytes calldata managerInput
98:    ) external view returns (uint256 nav) {
99:        (
100:            ManagerPrices[] memory managerPrices,
101:            PoolInfo[] memory pools,
102:            TokenId[][] memory tokenIds
103:        ) = abi.decode(managerInput, (ManagerPrices[], PoolInfo[], TokenId[][]));
104:
105:        if (keccak256(abi.encode(pools)) != vaultPools[vault]) revert InvalidPools();
106:
107:        address[] memory underlyingTokens = new address[](pools.length * 2);
108:
109:        // resolves stack too deep error
110:        address _vault = vault;
111:
112:        for (uint256 i = 0; i < pools.length; i++) {
113:            if (
114:                Math.abs(
115:                    managerPrices[i].poolPrice -
116:                        PanopticMath.twapFilter(pools[i].poolOracle, pools[i].twapWindow)
117:                ) > pools[i].maxPriceDeviation
118:            ) revert StaleOraclePrice();
119:
120:            uint256[2][] memory positionBalanceArray;
121:            int256 poolExposure0;
122:            int256 poolExposure1;
123:            {
124:                LeftRightUnsigned shortPremium;
125:                LeftRightUnsigned longPremium;
126:
127:                (shortPremium, longPremium, positionBalanceArray) = pools[i]
128:                    .pool
129:                    .getAccumulatedFeesAndPositionsData(_vault, true, tokenIds[i]);
130:
131:                poolExposure0 =
132:                    int256(uint256(shortPremium.rightSlot())) -
133:                    int256(uint256(longPremium.rightSlot()));
134:                poolExposure1 =
135:                    int256(uint256(longPremium.leftSlot())) -
136:                    int256(uint256(shortPremium.leftSlot()));
137:            }
138:
139:            uint256 numLegs;
140:            for (uint256 j = 0; j < tokenIds[i].length; j++) {
141:                if (positionBalanceArray[j][1] == 0) revert IncorrectPositionList();
142:                uint256 positionLegs = tokenIds[i][j].countLegs();
143:                for (uint256 k = 0; k < positionLegs; k++) {
144:                    (uint256 amount0, uint256 amount1) = Math.getAmountsForLiquidity(
145:                        managerPrices[i].poolPrice,
146:                        PanopticMath.getLiquidityChunk(
147:                            tokenIds[i][j],
148:                            k,
149:                            uint128(positionBalanceArray[j][1])
150:                        )
151:                    );
152:
153:                    if (tokenIds[i][j].isLong(k) == 0) {
154:                        unchecked {
155:                            poolExposure0 += int256(amount0);
156:                            poolExposure1 += int256(amount1);
157:                        }
158:                    } else {
159:                        unchecked {
160:                            poolExposure0 -= int256(amount0);
161:                            poolExposure1 -= int256(amount1);
162:                        }
163:                    }
164:                }
165:
166:                (LeftRightSigned longAmounts, LeftRightSigned shortAmounts) = PanopticMath
167:                    .computeExercisedAmounts(tokenIds[i][j], uint128(positionBalanceArray[j][1]));
168:
169:                poolExposure0 += int256(longAmounts.rightSlot()) - int256(shortAmounts.rightSlot());
170:                poolExposure1 += int256(longAmounts.leftSlot()) - int256(shortAmounts.leftSlot());
171:
172:                numLegs += positionLegs;
173:            }
174:
175:            if (numLegs != pools[i].pool.numberOfLegs(_vault)) revert IncorrectPositionList();
176:
177:            if (address(pools[i].token0) == address(0))
178:                pools[i].token0 = IERC20Partial(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE);
179:
180:            bool skipToken0 = false;
181:            bool skipToken1 = false;
182:
183:            // optimized for small number of pools
184:            for (uint256 j = 0; j < underlyingTokens.length; j++) {
185:                if (underlyingTokens[j] == address(pools[i].token0)) skipToken0 = true;
186:                if (underlyingTokens[j] == address(pools[i].token1)) skipToken1 = true;
187:
188:                if (underlyingTokens[j] == address(0)) {
189:                    if (!skipToken0) underlyingTokens[j] = address(pools[i].token0);
190:                    // ensure a gap is not created in the underlyingTokens array
191:                    if (!skipToken1)
192:                        underlyingTokens[j + (skipToken0 ? 0 : 1)] = address(pools[i].token1);
193:                    break;
194:                }
195:            }
196:
197:            if (!skipToken0)
198:                poolExposure0 += address(pools[i].token0) ==
199:                    address(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE)
200:                    ? int256(address(_vault).balance)
201:                    : int256(pools[i].token0.balanceOf(_vault));
202:            if (!skipToken1) poolExposure1 += int256(pools[i].token1.balanceOf(_vault));
203:
204:            uint256 collateralBalance = pools[i].pool.collateralToken0().balanceOf(_vault);
205:            poolExposure0 += int256(
206:                pools[i].pool.collateralToken0().previewRedeem(collateralBalance)
207:            );
208:
209:            collateralBalance = pools[i].pool.collateralToken1().balanceOf(_vault);
210:            poolExposure1 += int256(
211:                pools[i].pool.collateralToken1().previewRedeem(collateralBalance)
212:            );
213:
214:            // convert position values to underlying
215:            if (address(pools[i].token0) != underlyingToken) {
216:                int24 conversionTick = PanopticMath.twapFilter(
217:                    pools[i].oracle0,
218:                    pools[i].twapWindow
219:                );
220:                if (
221:                    Math.abs(conversionTick - managerPrices[i].token0Price) >
222:                    pools[i].maxPriceDeviation
223:                ) revert StaleOraclePrice();
224:
225:                uint160 conversionPrice = Math.getSqrtRatioAtTick(
226:                    pools[i].isUnderlyingToken0InOracle0 ? -conversionTick : conversionTick
227:                );
228:
229:                poolExposure0 = PanopticMath.convert0to1(poolExposure0, conversionPrice);
230:            }
231:
232:            if (address(pools[i].token1) != underlyingToken) {
233:                int24 conversionTick = PanopticMath.twapFilter(
234:                    pools[i].oracle1,
235:                    pools[i].twapWindow
236:                );
237:                if (
238:                    Math.abs(conversionTick - managerPrices[i].token1Price) >
239:                    pools[i].maxPriceDeviation
240:                ) revert StaleOraclePrice();
241:
242:                uint160 conversionPrice = Math.getSqrtRatioAtTick(
243:                    pools[i].isUnderlyingToken0InOracle1 ? conversionTick : -conversionTick
244:                );
245:
246:                poolExposure1 = PanopticMath.convert1to0(poolExposure1, conversionPrice);
247:            }
248:
249:            // debt in pools with negative exposure does not need to be paid back
250:            nav += uint256(Math.max(poolExposure0 + poolExposure1, 0));
251:        }
252:
253:        // underlying cannot be native (0x000/0xeee)
254:        bool skipUnderlying = false;
255:        for (uint256 i = 0; i < underlyingTokens.length; i++) {
256:            if (underlyingTokens[i] == underlyingToken) skipUnderlying = true;
257:        }
258:        if (!skipUnderlying) nav += IERC20Partial(underlyingToken).balanceOf(_vault);
259:    }
260:}

