    struct PoolInfo {
        PanopticPool pool;
        IERC20Partial token0;
        IERC20Partial token1;
        IV3CompatibleOracle poolOracle;
        IV3CompatibleOracle oracle0;
        bool isUnderlyingToken0InOracle0;
        IV3CompatibleOracle oracle1;
        bool isUnderlyingToken0InOracle1;
